    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Register signal handler for clean exit */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, OUTPUT_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request output lines */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 1)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }

    /* Main loop */
    while (keep_running) {
        int val1 = 1, val2 = 0;

        ret = gpiod_line_set_value(line1, val1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 1)");
            break;
        }
        printf("GPIO %d set to %d\n", OUTPUT_PIN_1, val1);

        ret = gpiod_line_set_value(line2, val2);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 2)");
            break;
        }
        printf("GPIO %d set to %d\n", OUTPUT_PIN_2, val2);

        usleep(100000); /* 0.1 seconds */
    }

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define POLL_TIMEOUT_MS 1000
#define SLEEP_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initially low */
    if (gpiod_line_request_output(line, "rpi-digital-output", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Digital output on GPIO %d (BCM). Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (value < 0 || value > 1) {
            fprintf(stderr, "Invalid GPIO value: %d (expected 0 or 1)\n", value);
            goto cleanup;
        }

        if (gpiod_line_set_value(line, value) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SLEEP_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    /* Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
    uint16_t config = 0x4000 | (0x04 << 12) | (0x02 << 9) | (0x01 << 8) | 0x00;
    if (i2c_write16(fd, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read16(fd, CONVERSION_REG, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion register\n");
            break;
        }
        double voltage = (raw / 32767.0) * REF_VOLTAGE;
        printf("Voltage: %.4f V\n", voltage);
        fflush(stdout);
        usleep(SAMPLE_INTERVAL_US);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

#define MLX90614_ADDR 0x5A
#define I2C_DEV "/dev/i2c-1"

static int i2c_fd = -1;

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int read_mlx90614(int fd, float *temp_c) {
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x2400, &raw) < 0) return -1;
    *temp_c = (float)raw / 100.0f;
    return 0;
}

int main(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MLX90614_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float temp;
        if (read_mlx90614(i2c_fd, &temp) < 0) {
            fprintf(stderr, "Failed to read MLX90614\n");
            close(i2c_fd);
            return 1;
        }
        printf("Temperature: %.2f C\n", temp);
        sleep(5);
    }

    close(i2c_fd);
    return 0;
}

