#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define CONSUMER "hcsr04"
#define TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa = {
        .sa_handler = sig_handler,
        .sa_flags = 0
    };
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            break;
        }

        if (val == 0) {
            sleep_ms(2);
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                break;
            }
            if (val == 0) {
                sleep_ms(2);
                val = gpiod_line_get_value(echo);
                if (val < 0) {
                    perror("gpiod_line_get_value(echo)");
                    break;
                }
                if (val == 0) {
                    printf("Sensor not responding (echo stuck low).\n");
                    break;
                }
            }
        }

        if (val == 1) {
            sleep_ms(2);
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                break;
            }
            if (val == 0) {
                long pulse_us = 0;
                sleep_ms(2);
                val = gpiod_line_get_value(echo);
                if (val < 0) {
                    perror("gpiod_line_get_value(echo)");
                    break;
                }
                if (val == 0) {
                    pulse_us = (long)val * 1000;
                }
                if (pulse_us > 0) {
                    float distance = pulse_us / 58.0f;
                    if (distance < 2.0f || distance > 400.0f) {
                        printf("Distance out of range: %.2f cm\n", distance);
                    } else {
                        printf("Distance: %.2f cm\n", distance);
                    }
                } else {
                    printf("Distance: invalid\n");
                }
            }
        }

        for (int i = 0; i < 60 && running; i++) {
            sleep_ms(100);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28
#define REG_CONV       0x00
#define REG_CONFIG     0x01
#define CONFIG_OS_BEGIN 0x8000
#define CONFIG_MUX_AIN0 0x4000
#define CONFIG_PGA_4_096V 0x0200
#define CONFIG_MODE_SINGLE 0x0100
#define CONFIG_DR_128SPS 0x0080
#define CONFIG_CQUE_NONE 0x0003
#define CONFIG_DEFAULT (CONFIG_OS_BEGIN | CONFIG_MUX_AIN0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_CQUE_NONE)

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int ads1115_init(int fd) {
    if (i2c_write16(fd, REG_CONFIG, CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "ads1115_init: config write failed\n");
        return -1;
    }
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    uint16_t cfg;
    if (i2c_read16(fd, REG_CONFIG, &cfg) < 0) return -1;
    if (!(cfg & CONFIG_OS_BEGIN)) {
        fprintf(stderr, "ads1115_read: config not started\n");
        return -1;
    }
    if (i2c_read16(fd, REG_CONV, &cfg) < 0) return -1;
    if (!(cfg & CONFIG_OS_BEGIN)) {
        fprintf(stderr, "ads1115_read: conversion not complete\n");
        return -1;
    }
    *raw = (int16_t)cfg;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "ADS1115 init failed (device absent or bus error)\n");
        close(fd);
        return 1;
    }

    printf("ADS1115 on 0x%02X initialized. Sampling AIN0 every 5 s. Ctrl+C to exit.\n", ADS1115_ADDR);

    while (g_running) {
        int16_t raw;
        if (ads1115_read(fd, &raw) < 0) {
            fprintf(stderr, "Read failed; continuing.\n");
        } else {
            if (raw == 0) {
                fprintf(stderr, "Warning: conversion returned 0 (sensor absent or bus error)\n");
            } else {
                printf("AIN0: %d\n", raw);
            }
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 18
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (keep_running) {
        int value = keep_running ? 1 : 0;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, value);
        fflush(stdout);
        sleep(1);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
