#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define SENSITIVITY 0.0001

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa = { .sa_handler = handle_signal };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t config = 0x8000; // single-shot, AIN0, 4.096V, 128 SPS
    if (i2c_write16(fd, CONFIG_REG, config) < 0) {
        perror("write config");
        close(fd);
        return EXIT_FAILURE;
    }

    usleep(10000);

    while (running) {
        uint16_t raw;
        if (i2c_read16(fd, CONVERSION_REG, &raw) < 0) {
            perror("read conversion");
            break;
        }
        double voltage = (raw / 32767.0) * REF_VOLTAGE;
        double adc = (raw / 32767.0) * SENSITIVITY;
        printf("ADC: %.6f, Voltage: %.6f\n", adc, voltage);
        usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN_1 2
#define OUTPUT_PIN_2 3
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret;

    /* Register signal handler for clean exit */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, OUTPUT_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 1)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request output lines */
    ret = gpiod_line_request_output(line1, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 1)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line2, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val1 = 1, val2 = 0;

        ret = gpiod_line_set_value(line1, val1);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 1)");
            break;
        }
        printf("GPIO %d set to %d\n", OUTPUT_PIN_1, val1);

        ret = gpiod_line_set_value(line2, val2);
        if (ret < 0) {
            perror("gpiod_line_set_value (pin 2)");
            break;
        }
        printf("GPIO %d set to %d\n", OUTPUT_PIN_2, val2);

        sleep(5);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");
    return EXIT_SUCCESS;
}

