#include <gpiod.h>

#define CONSUMER "rpi_gpio"
#define CHIP_PATH "/dev/gpiochip0"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
static const unsigned int offsets[4] = {4, 17, 22, 27};
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(CHIP_PATH);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", offsets[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", offsets[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        int vals[4] = {1, 0, 1, 0};
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", offsets[i]);
                release_resources();
                return EXIT_FAILURE;
            }
        }
        printf("GPIO 4: %d, GPIO 17: %d, GPIO 22: %d, GPIO 27: %d\n",
               vals[0], vals[1], vals[2], vals[3]);
        fflush(stdout);
        sleep(2);
    }

    release_resources();
    return EXIT_SUCCESS;
}

