#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int si7021_read_measurement(int fd, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0x44, 0x08};
    uint8_t data[9];

    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        return -1;
    }

    /* Datasheet: conversion takes ~12 ms; poll up to 20 ms */
    usleep(20000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0) {
        return -1;
    }

    /* Validate CRC (polynomial 0x31, init 0xFF) */
    uint8_t crc = 0xFF;
    for (int i = 0; i < 8; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    if (crc != data[8]) {
        fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n", crc, data[8]);
        return -1;
    }

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[3] << 8) | data[4];

    *humidity = (float)raw_h / 16383.0f * 100.0f;
    *temperature = (float)raw_t / 16383.0f * 165.0f - 40.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SI7021 measurement reader started (addr 0x%02X). Press Ctrl+C to exit.\n", SI7021_ADDR);

    while (g_running) {
        float temperature, humidity;

        if (si7021_read_measurement(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Measurement failed; continuing.\n");
        }

        /* Sleep 5 s in 100 ms slices so we can exit promptly on signal */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define NUM_READINGS 3

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    struct sigaction sa = { .sa_handler = handle_signal };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t config = 0x8000; /* single-shot, AIN0, +/-4.096V, 128 SPS */
    if (i2c_write16(fd, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_READINGS && running; i++) {
        usleep(100000); /* 100 ms conversion wait */
        uint16_t raw;
        if (i2c_read16(fd, CONVERSION_REG, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion register\n");
            close(fd);
            return EXIT_FAILURE;
        }
        double voltage = (raw / 32767.0) * REF_VOLTAGE;
        printf("Reading %d: %.4f V\n", i + 1, voltage);
        fflush(stdout);
    }

    close(fd);
    return EXIT_SUCCESS;
}

