        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Starting LED control on GPIO 8, 9, 10, 11, 23, 24. Press Ctrl+C to exit.\n");

    for (int cycle = 0; cycle < CYCLES && running; cycle++) {
        for (i = 0; i < NUM_PINS; i++) {
            int val = (i % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set GPIO %u\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %u set to %d\n", pins[i], val);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

