    line2 = gpiod_chip_get_line(chip, OUTPUT2);
    line3 = gpiod_chip_get_line(chip, OUTPUT3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        release_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line2, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line3, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        release_resources();
        return EXIT_FAILURE;
    }

    int ret = EXIT_SUCCESS;
    while (keep_running) {
        int val1 = 1, val2 = 0, val3 = 0;
        if (gpiod_line_set_value(line1, val1) < 0 ||
            gpiod_line_set_value(line2, val2) < 0 ||
            gpiod_line_set_value(line3, val3) < 0) {
