#define CONSUMER "output_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two output lines */
    line1 = gpiod_chip_get_line(chip, OUTPUT_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, OUTPUT_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 3)");
        goto cleanup;
    }

    printf("Output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val1 = 1, val2 = 0;

        /* Write values to the lines */
        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value (pin 2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value (pin 3)");
            goto cleanup;
        }

        /* Read back the values to verify */
        int r1 = gpiod_line_get_value(line1);
        int r2 = gpiod_line_get_value(line2);

        if (r1 < 0) {
            perror("gpiod_line_get_value (pin 2)");
            goto cleanup;
        }
        if (r2 < 0) {
            perror("gpiod_line_get_value (pin 3)");
            goto cleanup;
        }

        if (r1 != val1 || r2 != val2) {
            fprintf(stderr, "Warning: output mismatch (pin 2=%d, pin 3=%d)\n", r1, r2);
        }

        printf("GPIO 2 = %s, GPIO 3 = %s\n", r1 ? "HIGH" : "LOW", r2 ? "HIGH" : "LOW");

        /* Sleep 0.5 s, but wake early on signal */
        for (int i = 0; i < 5 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left low on exit */
    if (line1) gpiod_line_set_value(line1, 0);
    if (line2) gpiod_line_set_value(line2, 0);

    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

