        return EXIT_FAILURE;
    }

    /* Get output line */
    output_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!output_line) {
        perror("gpiod_chip_get_line (output)");
        goto cleanup;
    }

    /* Get input line */
    input_line = gpiod_chip_get_line(chip, INPUT_PIN);
    if (!input_line) {
        perror("gpiod_chip_get_line (input)");
        goto cleanup;
    }

