#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define CONSUMER "dht11-reader"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht11(struct gpiod_line *line, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int j = 0, i = 0;

    /* Start signal: pull low for >=1 ms, then high */
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    /* Wait for sensor response: low ~80 us, high ~80 us */
    int val;
    for (int w = 0; w < 255; w++) {
        val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == 0) break;
        usleep(1);
    }
    if (val != 0) return -1;

    /* Read 40 bits */
    for (int b = 0; b < 40; b++) {
        for (int w = 0; w < 255; w++) {
            val = gpiod_line_get_value(line);
            if (val < 0) return -1;
            if (val == 1) {
                data[j / 8] <<= 1;
                if (w == 1) data[j / 8] |= 1;
                j++;
            }
            usleep(1);
        }
        if (j < 40) break;
    }

    /* Check for checksum */
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0f;
    *temperature = (float)((data[2] << 8) + data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
