    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (read_dht11(line, &temperature, &humidity) != 0) {
        fprintf(stderr, "DHT11 read failed\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("DHT11: Temperature = %.1f C, Humidity = %.1f %%\n", temperature, humidity);

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

