        printf("Cycle %d/%d\n", cycle + 1, CYCLES);

        for (int i = 0; i < NUM_PINS; i++) {
            int val = 0;
            if (gpiod_line_get_value(lines[i]) < 0) {
                fprintf(stderr, "Failed to read line %d\n", OUTPUT_PIN_1 + i);
                goto cleanup;
            }
            if (val < 0 || val > 1) {
                fprintf(stderr, "Invalid value %d on line %d\n", val, OUTPUT_PIN_1 + i);
                goto cleanup;
            }
            values[i] = val;
