#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define OPT3001_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"

static int fd = -1;

void cleanup(int sig) {
    (void)sig;
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("open i2c device");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    uint8_t cmd = 0x00;
    if (write(fd, &cmd, 1) != 1) {
        perror("write cmd");
        close(fd);
        return 1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("read data");
        close(fd);
        return 1;
    }

    int raw = (buf[0] << 8) | buf[1];
    printf("Raw: %d\n", raw);
    fflush(stdout);

    close(fd);
    return 0;
}

