#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN 17
#define OTHER_PIN 18
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *out_line = NULL;
    struct gpiod_line *other_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the output line */
    out_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!out_line) {
        perror("gpiod_chip_get_line (output)");
        goto cleanup;
    }

    /* Get the other line */
    other_line = gpiod_chip_get_line(chip, OTHER_PIN);
    if (!other_line) {
        perror("gpiod_chip_get_line (other)");
        goto cleanup;
    }

    /* Request the output line as output, initial value LOW */
    if (gpiod_line_request_output(out_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (output)");
        goto cleanup;
    }

    /* Request the other line as input */
    if (gpiod_line_request_input(other_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Set output HIGH */
        if (gpiod_line_set_value(out_line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            goto cleanup;
        }
        printf("Output HIGH\n");
        fflush(stdout);

        /* Set other line HIGH */
        if (gpiod_line_set_value(other_line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            goto cleanup;
        }
        printf("Other HIGH\n");
        fflush(stdout);

        /* Set output LOW */
        if (gpiod_line_set_value(out_line, 0) < 0) {
            perror("gpiod_line_set_value (LOW)");
            goto cleanup;
        }
        printf("Output LOW\n");
        fflush(stdout);

        /* Set other line LOW */
        if (gpiod_line_set_value(other_line, 0) < 0) {
            perror("gpiod_line_set_value (LOW)");
            goto cleanup;
        }
        printf("Other LOW\n");
        fflush(stdout);

        /* Sleep 0.5 seconds, interruptible by signals */
        unsigned int remaining = 0;
        while (remaining < 500000 && keep_running) {
            remaining = usleep(1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (out_line) gpiod_line_release(out_line);
    if (other_line) gpiod_line_release(other_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("GPIO control stopped.\n");
    return ret;
}

