    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10; /* 1 second timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = init_serial(SERIAL_PORT);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port initialized on %s. Reading data...\n", SERIAL_PORT);

    char buffer[256];
    while (running) {
        ssize_t bytes = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            break;
        }
        if (bytes == 0) {
            /* Device disconnected or no data */
            break;
        }

        buffer[bytes] = '\0';
        printf("Received: %s\n", buffer);
    }

    if (close(fd) != 0) {
        fprintf(stderr, "Error closing serial port: %s\n", strerror(errno));
    }
    printf("Serial port closed.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
