static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_measurement(int fd, float *temperature, float *humidity) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, 0x00, &msb) < 0) return -1;
    if (i2c_read_reg8(fd, 0x01, &lsb) < 0) return -1;

    uint16_t raw_temp = ((uint16_t)msb << 8) | lsb;
    uint16_t raw_hum  = ((uint16_t)msb << 8) | lsb;

    if (raw_temp & 0x8000) raw_temp |= 0xFFFFF000;
    if (raw_hum  & 0x8000) raw_hum  |= 0xFFFFF000;

    *temperature = -46.85 + 175.72 * (float)raw_temp / 65536.0;
    *humidity    = 100.0 * (float)raw_hum  / 65536.0;
    return 0;
}

