    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get output line */
    out_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!out_line) {
        perror("gpiod_chip_get_line (output)");
        goto cleanup;
    }

    /* Get other line */
    other_line = gpiod_chip_get_line(chip, OTHER_PIN);
    if (!other_line) {
        perror("gpiod_chip_get_line (other)");
        goto cleanup;
    }

    /* Request output line as output, initial value LOW */
    if (gpiod_line_request_output(out_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (output)");
        goto cleanup;
    }

    /* Request other line as input */
    if (gpiod_line_request_input(other_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Set output HIGH */
        if (gpiod_line_set_value(out_line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            goto cleanup;
        }
        printf("Output HIGH\n");
        fflush(stdout);

        /* Read other line */
        int val = gpiod_line_get_value(other_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("Other line value: %d\n", val);
        fflush(stdout);

        /* Set output LOW */
        if (gpiod_line_set_value(out_line, 0) < 0) {
            perror("gpiod_line_set_value (LOW)");
            goto cleanup;
        }
        printf("Output LOW\n");
        fflush(stdout);

        usleep(50000); /* 0.05 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (out_line) {
        gpiod_line_release(out_line);
    }
    if (other_line) {
        gpiod_line_release(other_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("GPIO control stopped.\n");
    return ret;
}

