#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define I2C_DEVICE "/dev/i2c-1"

static int g_fd = -1;

static void cleanup(void) {
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup();
    exit(0);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    g_fd = open(I2C_DEVICE, O_RDWR);
    if (g_fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }

    uint8_t buf[6];
    if (read(g_fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        perror("read ADXL345");
        cleanup();
        return 1;
    }

    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);

    printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
    fflush(stdout);

    while (1) {
        sleep(0.1);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define NUM_CYCLES 50
#define STEP_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, "gpio-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d toggling %d times (0.1 s interval)...\n", GPIO_LINE, NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        int val = i % 2;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_LINE, val);
        usleep(STEP_DELAY_MS * 1000);
    }

    /* Ensure the line is left in a known state on exit */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nGPIO toggling complete.\n");
    return EXIT_SUCCESS;
}

