#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_ms) {
    int elapsed = 0;
    while (running && elapsed < timeout_ms) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v == val) return 0;
        usleep(1000);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2,
                      struct gpiod_line *line3, struct gpiod_line *line4) {
    int data[5] = {0, 0, 0, 0, 0};
    int idx = 0;

    /* Start signal: pull low for >=1ms, then high for >=50us */
    if (gpiod_line_request_output(line1, "dht22", 0) < 0) return -1;
    if (gpiod_line_set_value(line1, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line1, 1) < 0) return -1;
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line1, "dht22") < 0) return -1;

    /* Wait for sensor response: low ~80us, high ~80us */
    if (wait_for_line(line1, 0, 100) < 0) return -1;
    if (wait_for_line(line1, 1, 100) < 0) return -1;
    if (wait_for_line(line1, 0, 100) < 0) return -1;

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        if (wait_for_line(line2, 0, 100) < 0) return -1;
        if (wait_for_line(line3, 1, 100) < 0) return -1;
        if (wait_for_line(line4, 1, 100) < 0) return -1;
        if (wait_for_line(line4, 0, 100) < 0) return -1;
        data[idx / 8] <<= 1;
        if (wait_for_line(line3, 1, 100) < 0) return -1;
        data[idx / 8] |= 1;
        idx++;
    }

    /* Check for checksum */
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

    /* Parse data */
    int humidity = (data[0] << 8) | data[1];
    int temp = (data[2] << 8) | data[3];
    if (temp & 0x8000) temp = -(temp & 0x7FFF);

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL, *line4 = NULL;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    line3 = gpiod_chip_get_line(chip, DHT22_PIN_3);
    line4 = gpiod_chip_get_line(chip, DHT22_PIN_4);
    if (!line1 || !line2 || !line3 || !line4) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "dht22", 1) < 0 ||
        gpiod_line_request_output(line2, "dht22", 1) < 0 ||
        gpiod_line_request_output(line3, "dht22", 1) < 0 ||
        gpiod_line_request_output(line4, "dht22", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int rc = read_dht22(line1, line2, line3, line4);
        if (rc == 0) {
            printf("Humidity: %d%%, Temperature: %dC\n", (humidity / 10), temp);
        } else {
            fprintf(stderr, "Failed to read DHT22\n");
        }
        sleep(2);
    }

    ret = 0;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line4) gpiod_line_release(line4);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int vals[] = {100, 150, 200};
        for (size_t i = 0; i < sizeof(vals) / sizeof(vals[0]); ++i) {
            if (gpioPWM(PWM_PIN_1, vals[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
                break;
            }
            if (gpioPWM(PWM_PIN_2, vals[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
                break;
            }
            if (gpioPWM(PWM_PIN_3, vals[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_3);
                break;
            }
            printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
                   PWM_PIN_1, vals[i], PWM_PIN_2, vals[i], PWM_PIN_3, vals[i]);
        }
        gpioDelay(500000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

