#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define SSD1306_I2C_ADDR 0x3F
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES 8
#define SSD1306_CMD_BIT 0x80
#define SSD1306_NOOP 0x00
#define SSD1306_DISPLAY_ON 0xAE
#define SSD1306_DISPLAY_OFF 0x8D
#define SSD1306_SET_DISPLAY_CLOCK 0xD5
#define SSD1306_SET_DISPLAY_MEMORY 0xA8
#define SSD1306_SET_SEGREMAP 0xA1
#define SSD1306_SET_DUTYCYCLE 0x81
#define SSD1306_PAGE_SET 0xB0
#define SSD1306_ENTRY_MODE 0x20
#define SSD1306_DISPLAY_DATA 0xB2
#define SSD1306_CHR 0x40
#define SSD1306_NO_CHR 0x00
#define SSD1306_CMD 0x00
#define SSD1306_DATA 0x40

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        perror("i2c_write failed");
        return -1;
    }
    return 0;
}

int ssd1306_init(int fd) {
    uint8_t cmd[2] = {SSD1306_CMD_BIT, SSD1306_NOOP};
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_DISPLAY_OFF;
    cmd[1] = SSD1306_CMD_BIT | SSD1306_NOOP;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_DISPLAY_ON;
    cmd[1] = SSD1306_CMD_BIT | SSD1306_NOOP;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_SET_DISPLAY_CLOCK;
    cmd[1] = 0x80;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_SET_DISPLAY_MEMORY;
    cmd[1] = (SSD1306_HEIGHT - 1) << 4;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_SET_SEGREMAP;
    cmd[1] = 0x00;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_SET_DUTYCYCLE;
    cmd[1] = 0x3F;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_PAGE_SET;
    cmd[1] = 0;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_ENTRY_MODE;
    cmd[1] = SSD1306_NO_CHR;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    cmd[0] = SSD1306_CMD_BIT | SSD1306_DISPLAY_DATA;
    cmd[1] = SSD1306_CMD_BIT | SSD1306_NO_CHR;
    if (i2c_write(fd, cmd, 2) < 0) return -1;
    usleep(10000);

    return 0;
}

int ssd1306_clear(int fd) {
    uint8_t buf[1] = {SSD1306_CMD_BIT | SSD1306_DISPLAY_OFF};
    if (i2c_write(fd, buf, 1) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_DISPLAY_ON;
    if (i2c_write(fd, buf, 1) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_SET_DISPLAY_CLOCK;
    buf[1] = 0x80;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_SET_DISPLAY_MEMORY;
    buf[1] = (SSD1306_HEIGHT - 1) << 4;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_SET_SEGREMAP;
    buf[1] = 0x00;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_SET_DUTYCYCLE;
    buf[1] = 0x3F;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_PAGE_SET;
    buf[1] = 0;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_ENTRY_MODE;
    buf[1] = SSD1306_NO_CHR;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    buf[0] = SSD1306_CMD_BIT | SSD1306_DISPLAY_DATA;
    buf[1] = SSD1306_CMD_BIT | SSD1306_NO_CHR;
    if (i2c_write(fd, buf, 2) < 0) return -1;
    usleep(10000);

    return 0;
}

int ssd1306_display_value(int fd, int value) {
    uint8_t buf[1 + 2];
    buf[0] = SSD1306_CMD_BIT | SSD1306_DISPLAY_DATA;
    buf[1] = value;
    buf[2] = SSD1306_CMD_BIT | SSD1306_NO_CHR;
    if (i2c_write(fd, buf, 1 + 2) < 0) return -1;
    usleep(10000);
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        close(fd);
        return 1;
    }

    while (keep_running) {
        int val1 = 123;
        int val2 = 456;
        int val3 = 789;

        if (ssd1306_display_value(fd, val1) < 0) break;
        if (ssd1306_display_value(fd, val2) < 0) break;
        if (ssd1306_display_value(fd, val3) < 0) break;

        usleep(100000);
    }

    ssd1306_clear(fd);
    close(fd);
    return 0;
}

