#define ACCEL_ZOUT_H 0x3F
#define TEMP_OUT_H 0x41
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x68

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int mpu6050_init(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU6050: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Failed to read accel: %s\n", strerror(errno));
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    int fd = -1;
    int16_t ax, ay, az;
    int rc = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "Error: MPU6050 init failed\n");
        close(fd);
        return 1;
    }

    printf("MPU6050 initialized. Reading %d samples...\n", 100);

    for (int i = 0; i < 100 && running; i++) {
        if (read_accel(fd, &ax, &ay, &az) == 0) {
            printf("Accel: X=%6d Y=%6d Z=%6d\n", ax, ay, az);
        } else {
            fprintf(stderr, "Error: Read failed at sample %d\n", i);
            rc = 1;
            break;
        }
        usleep(10000);
    }

    if (close(fd) < 0) {
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
    }

    printf("\nExiting.\n");
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define OUTPUT_PIN_1 14
#define OUTPUT_PIN_2 15
#define CONSUMER "gpio_output"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 14)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, OUTPUT_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 15)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 14)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 15)");
        goto cleanup;
    }

    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO lines (val1=%d, val2=%d)\n", val1, val2);
            break;
        }

        if (val1 != 0 || val2 != 0) {
            if (gpiod_line_set_value(line1, val1) < 0) {
                perror("gpiod_line_set_value (pin 14)");
                break;
            }
            if (gpiod_line_set_value(line2, val2) < 0) {
                perror("gpiod_line_set_value (pin 15)");
                break;
            }
            printf("GPIO 14: %d, GPIO 15: %d\n", val1, val2);
        } else {
            printf("GPIO 14: 0, GPIO 15: 0\n");
        }

        for (int i = 0; i < 50 && running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <pthread.h>
#include <mqtt.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_pub"
#define MQTT_TOPIC "sensor_data"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 1
#define MQTT_CONSUMER_ID "rpi_sensor_pub_consumer"
#define READ_INTERVAL_US 10000
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static pthread_mutex_t mqtt_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_mqtt(void) {
    int rc = MQTT_connect(MQTT_CLIENT_ID, MQTT_BROKER_ADDRESS, MQTT_KEEPALIVE, MQTT_CONSUMER_ID);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT_connect failed: %s\n", MQTT_strerror(rc));
        return -1;
    }

    rc = MQTT_subscribe(MQTT_CLIENT_ID, MQTT_TOPIC, MQTT_QOS);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT_subscribe failed: %s\n", MQTT_strerror(rc));
        MQTT_disconnect(MQTT_CLIENT_ID, MQTT_BROKER_ADDRESS);
        return -1;
    }

    return 0;
}

static int publish_sensor_data(int sensor_id, int sensor_value) {
    char payload[64];
    int len = snprintf(payload, sizeof(payload), "{\"sensor_id\": %d, \"sensor_value\": %d}", sensor_id, sensor_value);
    if (len < 0 || (size_t)len >= sizeof(payload)) {
        fprintf(stderr, "Payload formatting failed\n");
        return -1;
    }

    MQTT_message *message = MQTT_message_new((void *)payload, (int)len);
    if (!message) {
        fprintf(stderr, "MQTT_message_new failed\n");
        return -1;
    }

    MQTT_delivery_token token;
    int rc = MQTT_publish(MQTT_CLIENT_ID, MQTT_TOPIC, message, MQTT_DUPACK | MQTT.QOS(MQTT_QOS), &token);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "MQTT_publish failed: %s\n", MQTT_strerror(rc));
        MQTT_message_free(message);
        return -1;
    }

    MQTT_message_free(message);
    return 0;
}

static void cleanup_mqtt(void) {
    MQTT_unsubscribe(MQTT_CLIENT_ID, MQTT_TOPIC);
    MQTT_disconnect(MQTT_CLIENT_ID, MQTT_BROKER_ADDRESS);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_mqtt() != 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_id = 1;
        int sensor_value = 0;

        if (pthread_mutex_lock(&mqtt_mutex) != 0) {
            perror("pthread_mutex_lock");
            break;
        }

        if (sensor_id < 1 || sensor_value < 0 || sensor_value > 100) {
            fprintf(stderr, "Invalid sensor reading (sensor_id=%d, sensor_value=%d)\n", sensor_id, sensor_value);
            pthread_mutex_unlock(&mqtt_mutex);
            continue;
        }

        if (pthread_mutex_unlock(&mqtt_mutex) != 0) {
            perror("pthread_mutex_unlock");
            break;
        }

        if (publish_sensor_data(sensor_id, sensor_value) != 0) {
            fprintf(stderr, "Failed to publish sensor data\n");
        }

        usleep(READ_INTERVAL_US);
    }

    cleanup_mqtt();
    pthread_mutex_destroy(&mqtt_mutex);
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 23
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("signal(SIGINT)");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("signal(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set to output. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (keep_running) {
        int state = (rand() % 2 == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE, state);
        sleep(5);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 22
#define VCC_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *vcc = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    vcc = gpiod_chip_get_line(chip, VCC_PIN);
    if (!trig || !echo || !vcc) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        goto cleanup;
    }
    if (gpiod_line_request_output(vcc, "hcsr04-vcc", 0) < 0) {
        perror("gpiod_line_request_output vcc");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value trig high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value trig low");
            break;
        }
        usleep(60);

        int timeout = 0;
        while (running && timeout < 200) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value echo");
                break;
            }
            if (val == 1) {
                timeout = 0;
                break;
            }
            usleep(1000);
            timeout++;
        }

        if (!running) break;
        if (timeout >= 200) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            break;
        }

        timeout = 0;
        while (running && timeout < 200) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value echo low");
                break;
            }
            if (val == 0) {
                timeout = 0;
                break;
            }
            usleep(1000);
            timeout++;
        }

        if (!running) break;
        if (timeout >= 200) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            break;
        }

        long long duration = 0;
        int valid = 0;
        int raw = gpiod_line_get_value(echo);
        if (raw < 0) {
            perror("gpiod_line_get_value echo low");
            break;
        }
        if (raw == 0) {
            duration = 0;
            valid = 1;
        } else {
            int timeout2 = 0;
            while (running && timeout2 < 200) {
                int val = gpiod_line_get_value(echo);
                if (val < 0) {
                    perror("gpiod_line_get_value echo low2");
                    break;
                }
                if (val == 0) {
                    timeout2 = 0;
                    break;
                }
                usleep(1000);
                timeout2++;
            }
            if (!running) break;
            if (timeout2 >= 200) {
                fprintf(stderr, "Timeout waiting for echo low to go high\n");
                break;
            }
            duration = (long long)timeout2 * 1000;
            valid = 1;
        }

        if (!valid) {
            fprintf(stderr, "Invalid echo reading\n");
            break;
        }

        float distance = (float)duration / 58.0;
        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            break;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (vcc) gpiod_line_release(vcc);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

