    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, values[i]) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %d\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               OUTPUT_1, values[0], OUTPUT_2, values[1], OUTPUT_3, values[2]);
        fflush(stdout);
        sleep(2);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_1"
#define MQTT_TOPIC "sensor_data"
#define SENSOR_READING_1 123
#define SENSOR_READING_2 456
#define SENSOR_READING_3 789

static MQTTClient client;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(int pin) {
    if (gpioSetMode(pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", pin);
        return -1;
    }
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d\n", pin);
        return -1;
    }
    return value;
}

static int publish_data(int sensor_value) {
    MQTTClient_message pubmsg;
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;
    pubmsg.dup = 0;
    pubmsg.will = 0;
    pubmsg.clientid = (int)strlen(MQTT_CLIENT_ID);
    pubmsg.username = (int)strlen(MQTT_CLIENT_ID);
    pubmsg.password = 0;
    pubmsg.usernameavailable = 0;
    pubmsg.willretain = 0;
    pubmsg.duplicitous = 0;
    pubmsg.payloadtype = 0;
    pubmsg.payloadencoding = 0;
    pubmsg.messageid = 0;
    pubmsg.consumed = 0;
    pubmsg.completioncode = 0;

    MQTTClient_deliveryToken token;
    token.dtok = 0;

    if (client.publish((const char *)MQTT_TOPIC, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish data to MQTT broker\n");
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (setup_gpio(17) != 0) {
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, 60, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to create MQTT client\n");
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_connect(client, 60) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_setCallbacks(client, NULL, NULL, NULL, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to set MQTT callbacks\n");
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler\n");
        MQTTClient_disconnect(client, 60);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    printf("Publishing sensor data to MQTT broker...\n");

    while (running) {
        int sensor_value1 = read_sensor(17);
        int sensor_value2 = read_sensor(18);
        int sensor_value3 = read_sensor(19);

        if (sensor_value1 == -1 || sensor_value2 == -1 || sensor_value3 == -1) {
            fprintf(stderr, "Error: Failed to read sensor data\n");
            break;
        }

        if (publish_data(sensor_value1) != 0) break;
        if (publish_data(sensor_value2) != 0) break;
        if (publish_data(sensor_value3) != 0) break;

        gpioDelay(1000000);
    }

    printf("Cleaning up...\n");
    MQTTClient_disconnect(client, 60);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 100
#define PWM_FREQ 1000
#define SLEEP_SECONDS 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (check permissions and hardware)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int value = 50;
        if (gpioPWM(PWM_PIN, value) != 0) {
            fprintf(stderr, "Failed to set PWM value on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("GPIO %d set to %d\n", PWM_PIN, value);
        fflush(stdout);
        gpioDelay(SLEEP_SECONDS * 1000000);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define CONSUMER "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL;
    int ret;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trigger, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    ret = gpiod_line_request_input(echo, CONSUMER);
    if (ret < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            break;
        }

        if (val == 1) {
            usleep(10000);
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo) timeout");
                break;
            }
            if (val == 0) {
                long dist = (val * 2) / 2.0;
                if (dist > 400.0) {
                    fprintf(stderr, "Distance out of range: %.2f cm\n", dist);
                } else {
                    printf("Distance: %.2f cm\n", dist);
                }
            }
        }

        usleep(200000);
    }

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_pwm(int pin, int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "gpioSetPWMrange failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int vals[] = {50, 100, 150, 200};
        for (size_t i = 0; i < sizeof(vals) / sizeof(vals[0]); ++i) {
            if (set_pwm(pins[i], vals[i]) != 0) {
                running = 0;
                break;
            }
        }
        if (running) gpioDelay(100000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

