#define MQTT_TOPIC "sensor_data"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 1
#define MQTT_CONSUMER_ID "rpi_sensor_pub_consumer"

static volatile sig_atomic_t running = 1;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (MQTTClient_connect(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTT_CONSUMER_ID) == MQTTCLIENT_SUCCESS) {
        MQTTClient_disconnect(&client, MQTT_KEEPALIVE);
    }
    MQTTClient_destroy(&client);
    pthread_mutex_destroy(&mutex);
}

static int read_sensor_data(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    char data_string[256];
    int sensor_value;
    bool valid = false;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    snprintf(data_string, sizeof(data_string), "%s, %s", timestamp, "unknown");

    sensor_value = read_sensor_data_from_device(data_string);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor data from device\n");
        return -1;
    }

    if (sensor_value > 100) {
        valid = true;
    } else {
        fprintf(stderr, "Sensor value out of range: %d\n", sensor_value);
    }

    return valid ? sensor_value : -1;
}

static void publish_sensor_data(int sensor_value) {
    MQTTClient_message pubmsg;
    MQTTClient_deliveryToken token;
    char payload[32];
    int ret;

    if (sensor_value < 0) {
        return;
    }

    snprintf(payload, sizeof(payload), "%d", sensor_value);

    memset(&pubmsg, 0, sizeof(pubmsg));
    pubmsg.qos = MQTT_QOS;
    pubmsg.retained = 0;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.topic = MQTT_TOPIC;

    memset(&token, 0, sizeof(token));

    ret = MQTTClient_publishMessage(&client, &pubmsg, &token);
    if (ret != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", MQTTClient_strerror(ret));
    }
}

