#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_ID 0xD0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading BMP280 ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Unexpected BMP280 ID: 0x%02X (expected 0x60)\n", id);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read(int fd, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading BMP280 data: %s\n", strerror(errno));
        return -1;
    }
    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *press = (float)raw_press / 1024.0f;
    *temp = (float)raw_temp / 16384.0f;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        goto cleanup;
    }

    printf("BMP280 initialized. Reading every 5 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        float temp, press;
        if (bmp280_read(fd, &temp, &press) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, press);
        } else {
            fprintf(stderr, "Failed to read BMP280 data.\n");
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = 512; /* 50% of 1000 */
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", PWM_PIN);
            break;
        }
        printf("GPIO %d set to %d\n", PWM_PIN, duty);
        fflush(stdout);
        gpioDelay(100000); /* 100 ms */
    }

    /* Ensure PWM is off before terminating */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define OUTPUT1 5
#define OUTPUT2 6
#define OUTPUT3 13
#define CONSUMER "led_control"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (line3) {
        gpiod_line_release(line3);
        line3 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT1);
    line2 = gpiod_chip_get_line(chip, OUTPUT2);
    line3 = gpiod_chip_get_line(chip, OUTPUT3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        release_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line2, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line3, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        release_resources();
        return EXIT_FAILURE;
    }

    int ret = EXIT_SUCCESS;
    while (keep_running) {
        int val1 = 1, val2 = 0, val3 = 0;
        if (gpiod_line_set_value(line1, val1) < 0 ||
            gpiod_line_set_value(line2, val2) < 0 ||
            gpiod_line_set_value(line3, val3) < 0) {
            perror("gpiod_line_set_value");
            ret = EXIT_FAILURE;
            break;
        }
        printf("GPIO%d: %d, GPIO%d: %d, GPIO%d: %d\n",
               OUTPUT1, val1, OUTPUT2, val2, OUTPUT3, val3);
        fflush(stdout);
        sleep(1);
    }

    release_resources();
    return ret;
}

