#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM1 2
#define PWM2 3
#define PWM3 18
#define PWM4 23
#define PWM5 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int pins[] = {PWM1, PWM2, PWM3, PWM4, PWM5};
    const char *names[] = {"PWM1", "PWM2", "PWM3", "PWM4", "PWM5"};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for %s (pin %d)\n", names[i], pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for %s (pin %d)\n", names[i], pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for %s (pin %d)\n", names[i], pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM outputs initialised on GPIO %s\n", names);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 1) != 0) {
                fprintf(stderr, "Error: gpioPWM set high failed for %s (pin %d)\n", names[i], pins[i]);
                break;
            }
            printf("PWM %s set HIGH\n", names[i]);
        }
        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioPWM set low failed for %s (pin %d)\n", names[i], pins[i]);
                break;
            }
            printf("PWM %s set LOW\n", names[i]);
        }
        gpioDelay(100000);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("\nPWM outputs terminated. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define STEP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: cannot set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: cannot set PWM range for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: cannot set PWM frequency for GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int duty1 = 128, duty2 = 64, duty3 = 192;
        if (gpioPWM(PWM_PIN_1, duty1) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on pin %d\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, duty2) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on pin %d\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, duty3) != 0) {
            fprintf(stderr, "Error: gpioPWM failed on pin %d\n", PWM_PIN_3);
            break;
        }
        printf("PWM: P1=%d P2=%d P3=%d\n", duty1, duty2, duty3);
        fflush(stdout);
        gpioDelay(STEP_DELAY_US);
    }

    for (int i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define CAPTURE_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int i;

    *fd = open(DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE, strerror(errno));
        return -1;
    }

    if (xioctl(*fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(*fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(*fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (buf.length < WIDTH * HEIGHT) {
        fprintf(stderr, "Insufficient buffer size\n");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_STREAMON, &buf) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static void capture_image(int fd) {
    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return;
    }

    memset(buffer, 0, WIDTH * HEIGHT);

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queueing buffer: %s\n", strerror(errno));
        munmap(buffer, WIDTH * HEIGHT);
        return;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeueing buffer: %s\n", strerror(errno));
        munmap(buffer, WIDTH * HEIGHT);
        return;
    }

    if (munmap(buffer, WIDTH * HEIGHT) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
    }

    FILE *fp = fopen("image.jpg", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing: %s\n", strerror(errno));
        return;
    }

    if (fwrite(buffer, 1, WIDTH * HEIGHT, fp) != WIDTH * HEIGHT) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
    }

    printf("Image saved as image.jpg\n");
}

int main(void) {
    int fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd) < 0) {
        return 1;
    }

    printf("Starting image capture loop. Press Ctrl+C to exit.\n");

    while (running) {
        capture_image(fd);
        sleep(CAPTURE_INTERVAL);
    }

    if (fd >= 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &buf);
        close(fd);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

