    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(*fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    if (buf.length < (IMAGE_WIDTH * IMAGE_HEIGHT * 3)) {
        fprintf(stderr, "Insufficient buffer size\n");
        close(*fd);
        return -1;
    }

    if (xioctl(*fd, VIDIOC_STREAMON, &buf) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static void capture_image(int fd) {
    struct v4l2_buffer buf;
    char *buffer;
    size_t bytes_written;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return;
    }

    buffer = (char *)mmap(NULL, buf.length, PROT_READ, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_QBUF, &buf);
        return;
    }

    bytes_written = write(fd, buffer, buf.length);
    if (bytes_written != buf.length) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
    }

    munmap(buffer, buf.length);
    xioctl(fd, VIDIOC_QBUF, &buf);
}

static void save_image(const char *filename, const char *image_data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return;
    }

    if (fwrite(image_data, 1, size, fp) != size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
    }
}

int main(void) {
    int fd;
    char *image_data = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_camera(&fd) != 0) {
        fprintf(stderr, "Camera initialization failed\n");
        goto cleanup;
    }

    image_data = (char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (image_data == NULL) {
        fprintf(stderr, "Error allocating memory for image data\n");
        goto cleanup;
    }

    printf("Capturing image...\n");
    capture_image(fd);

    if (image_data != NULL) {
        printf("Saving image...\n");
        save_image("image.jpg", image_data, IMAGE_WIDTH * IMAGE_HEIGHT * 3);
        free(image_data);
    }

    printf("Image saved successfully.\n");
    ret = 0;

cleanup:
    if (fd >= 0) {
        xioctl(fd, VIDIOC_STREAMOFF, &buf);
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN_1 2
#define OUTPUT_PIN_2 3
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the output lines */
    line1 = gpiod_chip_get_line(chip, OUTPUT_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, OUTPUT_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 3)");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val1 = 1, val2 = 0;

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value (pin 2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value (pin 3)");
            goto cleanup;
        }

        printf("GPIO 2 set to %d, GPIO 3 set to %d\n", val1, val2);
        fflush(stdout);

        /* Sleep 0.5 s, but wake early on signal */
        for (int i = 0; i < 5 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");
    return ret;
}

