#define CONSUMER "gpio_control"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *output_line = NULL;
static struct gpiod_line *other_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    output_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!output_line) {
        perror("gpiod_chip_get_line (output)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    other_line = gpiod_chip_get_line(chip, OTHER_PIN);
    if (!other_line) {
