        fflush(stdout);

        ret = gpiod_line_set_value(other_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (other, 1)");
            break;
        }
        printf("Other output set to HIGH\n");
        fflush(stdout);

