#define OUTPUT1 18
#define OUTPUT2 23
#define OUTPUT3 24
#define CONSUMER "led_control"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line1 = NULL;
static struct gpiod_line *line2 = NULL;
static struct gpiod_line *line3 = NULL;
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    if (line1) {
        gpiod_line_release(line1);
        line1 = NULL;
    }
    if (line2) {
        gpiod_line_release(line2);
        line2 = NULL;
    }
    if (line3) {
        gpiod_line_release(line3);
        line3 = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, OUTPUT1);
    line2 = gpiod_chip_get_line(chip, OUTPUT2);
    line3 = gpiod_chip_get_line(chip, OUTPUT3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        release_resources();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line2, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line3, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        release_resources();
        return EXIT_FAILURE;
    }

    int ret = EXIT_SUCCESS;
    while (keep_running) {
        int val1 = 1, val2 = 0, val3 = 0;
        if (gpiod_line_set_value(line1, val1) < 0 ||
            gpiod_line_set_value(line2, val2) < 0 ||
            gpiod_line_set_value(line3, val3) < 0) {
            perror("gpiod_line_set_value");
            ret = EXIT_FAILURE;
            break;
        }
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               OUTPUT1, val1, OUTPUT2, val2, OUTPUT3, val3);
        fflush(stdout);
        sleep(1);
    }

    release_resources();
    return ret;
}

