#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22-reader"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Start with line high for >18 ms pull-up */
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(high)");
        goto cleanup;
    }
    usleep(20000); /* 20 ms */

    /* Switch to input to read data */
    if (gpiod_line_request_input(line, CONSUMER) < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    /* Wait for DHT22 to pull low (response signal) */
    int timeout = 0;
    while (gpiod_line_get_value(line) == 1 && running) {
        usleep(100);
        timeout += 100;
        if (timeout >= 100000) { /* 100 ms timeout */
            fprintf(stderr, "DHT22: no response (line stuck high)\n");
            goto cleanup;
        }
    }

    if (!running) {
        goto cleanup;
    }

    /* Read 40 bits */
    int data[40] = {0};
    int bit_idx = 0;
    int timeout = 0;

    while (bit_idx < 40 && running) {
        /* Wait for line to go low (start of bit) */
        timeout = 0;
        while (gpiod_line_get_value(line) == 1 && running) {
            usleep(1);
            timeout++;
            if (timeout >= 100) {
                fprintf(stderr, "DHT22: timeout waiting for bit low\n");
                goto cleanup;
            }
        }

        if (!running) {
            goto cleanup;
        }

        /* Measure high pulse width: ~26-28 us = '0', ~70 us = '1' */
        timeout = 0;
        while (gpiod_line_get_value(line) == 0 && running) {
            usleep(1);
            timeout++;
            if (timeout >= 100) {
                fprintf(stderr, "DHT22: timeout waiting for bit high end\n");
                goto cleanup;
            }
        }
        if (!running) {
            goto cleanup;
        }

        /* >50 us high pulse => '1' */
        if (timeout > 50) {
            data[bit_idx] = 1;
        } else {
            data[bit_idx] = 0;
        }

        bit_idx++;
    }

    if (!running) {
        goto cleanup;
    }

    /* Check for checksum */
    if (data[7] + data[8] + data[9] + data[10] != data[26] + data[27] + data[28] + data[29]) {
        fprintf(stderr, "DHT22: checksum error\n");
        goto cleanup;
    }

    /* Parse humidity (16-bit, big-endian) and temperature (16-bit, big-endian) */
    int humidity = (data[0] << 8) | data[1];
    int temp_raw = (data[2] << 8) | data[3];
    int temp = (data[4] << 8) | data[5];
    int temp_valid = (data[4] == 1 && data[5] == 0) ? 1 : 0;

    if (temp_valid) {
        float temp_c = (float)temp_raw / 10.0f;
        if (temp_c < -40.0f || temp_c > 80.0f) {
            fprintf(stderr, "DHT22: temperature out of range (%d)\n", temp_c);
            goto cleanup;
        }
    } else {
        fprintf(stderr, "DHT22: temperature not valid\n");
        goto cleanup;
    }

    if (humidity > 100) {
        fprintf(stderr, "DHT22: humidity out of range (%d)\n", humidity);
        goto cleanup;
    }

    printf("DHT22: Humidity = %d%%, Temperature = %.1f C\n", humidity, temp_c);
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

