#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "mcp3008_sensor"
#define MQTT_TOPIC "sensor_data"
#define MCP3008_CHANNEL 0
#define MCP3008_VREF 3.3f
#define ADC_MAX 1023.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (gpioSetMode(18, PI_OUTPUT) < 0) return -1;
    gpioWrite(18, 0);
    gpioDelay(1);

    int bytes = serWrite(tx, 3);
    if (bytes != 3) return -1;

    gpioDelay(1000);

    bytes = serRead(rx, 3);
    if (bytes != 3) return -1;

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void publish_data(int adc_value) {
    MQTTClient_message pubmsg;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient client = MQTTClient_connect(MQTT_BROKER, MQTT_CLIENT_ID, &conn_opts, NULL);
    if (!client) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        return;
    }

    MQTTClient_messagePub message = MQTTClient_messagePub_initializer;
    message.payload = (void *)adc_value;
    message.payloadlen = (int)sizeof(int);
    message.qos = 0;
    message.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(client);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    while (running) {
