    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("i2c_write_byte: write failed");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int values[] = {1, 2, 3, 4};
    int count = sizeof(values) / sizeof(values[0]);

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < count; i++) {
            if (!running) break;
            if (i2c_write_byte(fd, values[i]) < 0) {
