#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24

#define PWM_RANGE 255
#define STEP_DELAY_US 100000  /* 0.1 s */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

static int set_pwm(unsigned pin, unsigned level) {
    if (gpioPWM(pin, level) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    unsigned pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed on pin %u\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "gpioSetPWMrange failed on pin %u\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "gpioPWM initial off failed on pin %u\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        if (set_pwm(PWM_PIN_1, 1) != 0) break;
        if (set_pwm(PWM_PIN_2, 1) != 0) break;
        if (set_pwm(PWM_PIN_3, 1) != 0) break;
        printf("PWM: 1 1 1\n");
        fflush(stdout);
        gpioDelay(STEP_DELAY_US);
    }

    /* Clean shutdown: turn all PWM outputs off */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hc-sr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    printf("HC-SR04 initialized. Trigger=GPIO%d, Echo=GPIO%d\n", TRIGGER_PIN, ECHO_PIN);

    while (running) {
        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value(trigger high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger low)");
            break;
        }
        usleep(2);

        int timeout = 100;
        while (running && timeout > 0) {
            int val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                break;
            }
            if (val == 1) {
                usleep(1000);
                int val2 = gpiod_line_get_value(echo);
                if (val2 < 0) {
                    perror("gpiod_line_get_value(echo timeout)");
                    break;
                }
                if (val2 == 0) {
                    printf("Distance: %.2f cm\n", 0.0);
                } else {
                    printf("Distance: %.2f cm\n", (float)(val2 - 1) * 0.0343);
                }
                break;
            }
            usleep(1000);
            timeout--;
        }

        if (!running) break;
        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

