#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17
#define NUM_PINS 3
#define CYCLES 3
#define CYCLE_DELAY 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int pins[NUM_PINS] = {GPIO_2, GPIO_3, GPIO_17};
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = 1;
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %d set to %d\n", pins[i], values[i]);
        }

        sleep(CYCLE_DELAY);

        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = 0;
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %d set to %d\n", pins[i], values[i]);
        }

        sleep(CYCLE_DELAY);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

