static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_byte: write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_byte: read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int sht31_reset(int fd) {
    if (i2c_write_byte(fd, SHT31_RESET, 0x00) < 0) return -1;
    usleep(50000);
    if (i2c_write_byte(fd, SHT31_RESET, 0x01) < 0) return -1;
    usleep(50000);
    return 0;
}

static int sht31_read(int fd, float *temp, float *hum) {
    uint8_t id;
    if (i2c_read_byte(fd, SHT31_ID, &id) < 0) return -1;
    if (id != 0x31) {
        fprintf(stderr, "SHT31 ID mismatch: got 0x%02X, expected 0x31\n", id);
        return -1;
    }

    if (i2c_write_byte(fd, SHT31_MEAS_HIGH, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, SHT31_MEAS_LOW,  0x00) < 0) return -1;
    if (i2c_write_byte(fd, SHT31_CTRL,    0x00) < 0) return -1;

    usleep(50000);

    uint8_t status;
    for (int i = 0; i < 50; i++) {
        if (i2c_read_byte(fd, SHT31_STATUS, &status) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if ((status & 0x01) != 0) {
        fprintf(stderr, "SHT31 measurement timeout\n");
        return -1;
    }

    uint8_t msb, lsb;
    if (i2c_read_byte(fd, SHT31_MEAS_HIGH, &msb) < 0) return -1;
    if (i2c_read_byte(fd, SHT31_MEAS_LOW,  &lsb) < 0) return -1;

    uint16_t raw_h = (msb << 8) | lsb;
    uint16_t raw_t = (msb << 8) | lsb;

    *hum = (float)raw_h / 100.0f;
    *temp = (float)raw_t / 10.0f - 40.0f;

    if (*temp < -40.0f || *temp > 125.0f) {
        fprintf(stderr, "SHT31 reading out of range: T=%.1f C, H=%.1f %%\n", *temp, *hum);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (sht31_reset(fd) < 0) {
        fprintf(stderr, "SHT31 reset failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        float temp, hum;
        if (sht31_read(fd, &temp, &hum) == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        } else {
            fprintf(stderr, "SHT31 read failed\n");
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

