#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM pins initialised: %d, %d, %d, %d\n", PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);
    printf("State: OFF\n");
    fflush(stdout);

    while (running) {
        int state = 1;
        if (gpioWrite(PWM_PIN_1, state) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for pin %d\n", PWM_PIN_1);
            break;
        }
        if (gpioWrite(PWM_PIN_2, state) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for pin %d\n", PWM_PIN_2);
            break;
        }
        if (gpioWrite(PWM_PIN_3, state) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for pin %d\n", PWM_PIN_3);
            break;
        }
        if (gpioWrite(PWM_PIN_4, state) != 0) {
            fprintf(stderr, "Error: gpioWrite failed for pin %d\n", PWM_PIN_4);
            break;
        }
        printf("State: %s\n", state ? "ON" : "OFF");
        fflush(stdout);
        gpioDelay(100000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN_1 2
#define OUTPUT_PIN_2 3
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two output lines */
    line1 = gpiod_chip_get_line(chip, OUTPUT_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (pin 2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, OUTPUT_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (pin 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (pin 3)");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val1 = 1, val2 = 0;

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value (pin 2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value (pin 3)");
            goto cleanup;
        }

        printf("GPIO 2 set to %d, GPIO 3 set to %d\n", val1, val2);
        fflush(stdout);

        /* Sleep 1 second, interruptible by signals */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("GPIO control stopped.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN 2
#define OTHER_PIN 17
#define POLL_INTERVAL_SEC 60

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *out_line = NULL;
    struct gpiod_line *other_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the output line */
    out_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!out_line) {
        perror("gpiod_chip_get_line (output)");
        goto cleanup;
    }

    /* Get the other line */
    other_line = gpiod_chip_get_line(chip, OTHER_PIN);
    if (!other_line) {
        perror("gpiod_chip_get_line (other)");
        goto cleanup;
    }

    /* Request the output line as output, initial value LOW */
    if (gpiod_line_request_output(out_line, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output (output)");
        goto cleanup;
    }

    /* Request the other line as input */
    if (gpiod_line_request_input(other_line, "gpio-toggle") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Set output HIGH */
        if (gpiod_line_set_value(out_line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            goto cleanup;
        }
        printf("Output HIGH\n");
        fflush(stdout);

        /* Read other line */
        int val = gpiod_line_get_value(other_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("Other line value: %d\n", val);
        fflush(stdout);

        /* Set output LOW */
        if (gpiod_line_set_value(out_line, 0) < 0) {
            perror("gpiod_line_set_value (LOW)");
            goto cleanup;
        }
        printf("Output LOW\n");
        fflush(stdout);

        /* Read other line again */
        val = gpiod_line_get_value(other_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("Other line value: %d\n", val);
        fflush(stdout);

        /* Sleep for the poll interval, checking keep_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (out_line) gpiod_line_release(out_line);
    if (other_line) gpiod_line_release(other_line);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Exiting cleanly.\n");

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17
#define NUM_PINS 3
#define CYCLES 3

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_2 + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_2 + i);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_2 + i);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    int cycles_completed = 0;
    while (keep_running) {
        for (int i = 0; i < NUM_PINS && keep_running; i++) {
            int val = (i % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set GPIO %d\n", GPIO_2 + i);
                release_resources();
                return EXIT_FAILURE;
            }
            printf("GPIO %d set to %d\n", GPIO_2 + i, val);
        }
        if (keep_running) {
            cycles_completed++;
            if (cycles_completed < CYCLES) {
                sleep(1);
            }
        }
    }

    release_resources();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN 2
#define CONSUMER "gpio_output"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the output line */
    line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle output while running */
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("GPIO %d set HIGH\n", OUTPUT_PIN);
        fflush(stdout);

        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("GPIO %d set LOW\n", OUTPUT_PIN);
        fflush(stdout);
    }

    /* Clean up: ensure line is low before releasing */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

