    if (gpioSetMode(CHIP, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPullUpDown(CHIP, PI_PUD_OFF);

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        gpioSetMode(i, PI_OUTPUT);
        gpioWrite(i, 0);
    }

    while (running) {
        for (int i = 0; i < NUM_LEDS; i++) {
            gpioWrite(i, 1);
            gpioDelay(100);
            gpioWrite(i, 0);
            gpioDelay(100);
