#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DIR "/sys/bus/w1/devices"
#define W1_FILE "w1_slave"
#define W1_ID "28-xxxxxxxxxxxxxxx"
#define READ_INTERVAL 5
#define MAX_READS 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_w1_id(const char *path, char *buf, size_t len) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(buf, len, fp) == NULL) {
        fprintf(stderr, "Error reading %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int read_temperature(const char *path, float *temp) {
    char id[17];
    if (read_w1_id(path, id, sizeof(id)) != 0) {
        return -1;
    }
    if (strcmp(id, W1_ID) != 0) {
        fprintf(stderr, "Unexpected device ID: %s\n", id);
        return -1;
    }
    char data[256];
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fgets(data, sizeof(data), fp) == NULL) {
        fprintf(stderr, "Error reading %s\n", path);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (strstr(data, "YES") == NULL) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    char *t = strstr(data, "t=");
    if (!t) {
        fprintf(stderr, "Temperature data not found\n");
        return -1;
    }
    errno = 0;
    long temp_raw = strtol(t + 2, NULL, 10);
    if (errno != 0) {
        fprintf(stderr, "Error converting temperature\n");
        return -1;
    }
    *temp = (float)temp_raw / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting DS18B20 temperature readings (3 total)...\n");

    for (int i = 0; i < MAX_READS && running; i++) {
        float temp;
        if (read_temperature(W1_FILE, &temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        if (i < MAX_READS - 1 && running) {
            sleep(READ_INTERVAL);
        }
    }

    printf("Exiting.\n");
    return 0;
}

