#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22-reader"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int target, int timeout_ms) {
    int elapsed = 0;
    while (running && elapsed < timeout_ms) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        usleep(1000);
        elapsed += 1000;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int bit_idx = 0;

    /* Start signal: pull low for >=1ms, then high */
    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(30);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(40);

    /* Switch to input */
    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    /* Wait for sensor response: low then high */
    if (wait_for_line(line, 0, 100) < 0) return -1;
    if (wait_for_line(line, 1, 100) < 0) return -1;

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        if (wait_for_line(line, 0, 100) < 0) return -1;
        usleep(40);
        int counter = 0;
        while (running && gpiod_line_get_value(line) == 1) {
            counter++;
            usleep(1);
        }
        if (counter > 50) {
            data[bit_idx / 8] |= (1 << (7 - (bit_idx % 8)));
        }
        bit_idx++;
    }

    /* Check for checksum */
    if (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
        *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
        if (data[2] & 0x80) *temperature = -*temperature;
        return 0;
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float humidity, temperature;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("DHT22 on GPIO %d. Press Ctrl+C to exit.\n", DHT22_PIN);

    for (int i = 0; i < 3 && running; i++) {
        if (read_dht22(line, &humidity, &temperature) == 0) {
            printf("DHT22: Humidity = %.1f%%, Temperature = %.1fC\n", humidity, temperature);
        } else {
            fprintf(stderr, "DHT22: Read failed (attempt %d)\n", i + 1);
        }
        sleep(2);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    printf("\nExiting.\n");
    return EXIT_SUCCESS;
}

