    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PINS[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_PINS[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    for (int cycle = 0; cycle < CYCLES && keep_running; cycle++) {
        int vals[NUM_PINS];
        for (int i = 0; i < NUM_PINS; i++) {
            vals[i] = 1;
        }
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO %d\n", GPIO_PINS[i]);
                release_resources();
                return EXIT_FAILURE;
            }
            printf("GPIO %d set to %d\n", GPIO_PINS[i], vals[i]);
        }
        usleep(DELAY_MS * 1000);
    }

    printf("\nExiting...\n");
    release_resources();
    return EXIT_SUCCESS;
}

