#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "led_control"
#define NUM_PINS 7
#define CYCLES 100
#define DELAY_MS 500

static const unsigned int pins[NUM_PINS] = {4, 17, 22, 23, 24, 25, 27};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("LED control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_PINS && keep_running; i++) {
            int val = (i % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set GPIO %u\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("GPIO %u set to %d\n", pins[i], val);
        }
        if (keep_running) usleep(DELAY_MS * 1000);
    }

    cleanup();
    printf("LED control stopped.\n");
    return EXIT_SUCCESS;
}

