        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, val3) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO17=%d, GPIO23=%d, GPIO24=%d\n", val1, val2, val3);
        fflush(stdout);

        /* Sleep 1 second, interruptible by signals */
        for (int i = 0; i < 10 && keep_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);

    printf("LED control stopped.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define CONSUMER "dht22-reader"
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_line(struct gpiod_line *line, int target, int timeout_ms) {
    int elapsed = 0;
    while (elapsed < timeout_ms) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        usleep(1000);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line1, struct gpiod_line *line2,
                      float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int bit_idx = 0;

    /* Start signal: pull low for >=1ms, then high */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) return -1;
    usleep(2000);
    if (gpiod_line_set_value(line1, 1) < 0) return -1;
    usleep(30);

    /* Switch to input */
    if (gpiod_line_request_input(line1, CONSUMER) < 0) return -1;

    /* Switch to input */
    if (gpiod_line_request_input(line2, CONSUMER) < 0) return -1;

    /* Wait for sensor response: low then high */
    if (wait_for_line(line2, 0, 1000) < 0) return -1;
    if (wait_for_line(line2, 1, 1000) < 0) return -1;

    /* Read 40 bits */
    for (int i = 0; i < 40; i++) {
        if (wait_for_line(line1, 0, 1000) < 0) return -1;
        usleep(40);
        int val = gpiod_line_get_value(line1);
        if (val < 0) return -1;
        if (val == 0) {
            data[bit_idx / 8] <<= 1;
            if (i % 2 == 0) data[bit_idx / 8] |= 1;
            bit_idx++;
        }
        if (bit_idx % 8 == 0) {
            if (wait_for_line(line2, 0, 1000) < 0) return -1;
            usleep(40);
            int val2 = gpiod_line_get_value(line2);
            if (val2 < 0) return -1;
            if (val2 == 0) {
                data[4] = (data[4] << 1) | 1;
            }
        }
    }

    /* Check checksum */
    int checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error\n");
        return -1;
    }

    *humidity = (float)data[0] / 10.0f;
    *temperature = (float)data[2] / 10.0f;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    float temperature, humidity;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("DHT22 reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(line1, line2, &temperature, &humidity) == 0) {
                printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed\n", attempt + 1);
            if (attempt < MAX_RETRIES - 1) sleep(1);
        }

        if (!success) {
            fprintf(stderr, "DHT22 not responding after %d attempts. Exiting.\n", MAX_RETRIES);
            break;
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && running; i++) sleep(1);
    }

    /* Release lines and chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("DHT22 reader stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
