#define CONSUMER "led_control"
#define NUM_PINS 5
#define DELAY_MS 1000

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_PINS];
static const unsigned int pin_numbers[NUM_PINS] = {8, 9, 10, 11, 23};
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_numbers[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_numbers[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int val = (i % 2 == 0) ? 1 : 0;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to set GPIO %u\n", pin_numbers[i]);
                release_resources();
                return EXIT_FAILURE;
            }
            printf("GPIO %u set to %d\n", pin_numbers[i], val);
        }
        usleep(DELAY_MS * 1000);
    }

    release_resources();
    return EXIT_SUCCESS;
}

