#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 4000000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

static int spi_setup(int fd) {
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_max31855(int fd, uint32_t *raw) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
           ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];
    return 0;
}

static void print_max31855(uint32_t raw) {
    if (raw & 0x00010000) {
        printf("MAX31855: ");
    }
    if (raw & 0x00000007) {
        printf("Fault ");
    }
    if (raw & 0x00000003) {
        printf("Ins ");
    }
    if (raw & 0x00000002) {
        printf("Open ");
    }
    if (raw & 0x00000001) {
        printf("Short ");
    }
    if (raw & 0x00000004) {
        printf("GND ");
    }
    if (raw & 0x00000006) {
        printf("Open ");
    }
    if (raw & 0x00000008) {
        printf("Short ");
    }
    if (raw & 0x00000010) {
        printf("Fault ");
    }
    printf("C=%u.%u\n", (raw >> 18) & 0xFF, (raw >> 12) & 0xFF);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = spi_open(SPI_DEVICE);
    if (fd < 0) {
        return 1;
    }

    if (spi_setup(fd) < 0) {
        close(fd);
        return 1;
    }

    uint32_t raw;
    while (running) {
        if (read_max31855(fd, &raw) == 0) {
            print_max31855(raw);
        } else {
            fprintf(stderr, "Failed to read from MAX31855.\n");
        }
        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define OUTPUT_PIN 17
#define INPUT_PIN 18
#define CONSUMER "gpio_control"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *out_line = NULL;
    struct gpiod_line *in_line = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get output line */
    out_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!out_line) {
        perror("gpiod_chip_get_line (output)");
        goto cleanup;
    }

    /* Get input line */
    in_line = gpiod_chip_get_line(chip, INPUT_PIN);
    if (!in_line) {
        perror("gpiod_chip_get_line (input)");
        goto cleanup;
    }

    /* Request output line */
    if (gpiod_line_request_output(out_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (output)");
        goto cleanup;
    }

    /* Request input line */
    if (gpiod_line_request_input(in_line, CONSUMER) < 0) {
        perror("gpiod_line_request_input (input)");
        goto cleanup;
    }

    printf("GPIO control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Set output high */
        if (gpiod_line_set_value(out_line, 1) < 0) {
            perror("gpiod_line_set_value (high)");
            goto cleanup;
        }
        printf("Output HIGH\n");
        fflush(stdout);

        /* Read input */
        int val = gpiod_line_get_value(in_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("Input: %d\n", val);
        fflush(stdout);

        usleep(100000); /* 0.1 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (out_line) {
        gpiod_line_release(out_line);
    }
    if (in_line) {
        gpiod_line_release(in_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("\nGPIO control stopped.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define VCC_PIN 18
#define GND_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *vcc = NULL, *gnd = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    vcc = gpiod_chip_get_line(chip, VCC_PIN);
    gnd = gpiod_chip_get_line(chip, GND_PIN);
    if (!trig || !echo || !vcc || !gnd) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hcsr04-echo") < 0 ||
        gpiod_line_request_output(vcc, "hcsr04-vcc", 1) < 0 ||
        gpiod_line_request_output(gnd, "hcsr04-gnd", 0) < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    printf("HC-SR04 initialized. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }
        usleep(2);
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("set trigger high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }
        usleep(2);

        long long start_ns = 0, end_ns = 0, pulse_ns = 0;
        int val;

        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                break;
            }
            if (val == 1) {
                start_ns = (long long)clock_gettime(CLOCK_MONOTONIC, NULL);
            }
            usleep(100);
            if (!running) break;
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                break;
            }
            if (val == 0) {
                end_ns = (long long)clock_gettime(CLOCK_MONOTONIC, NULL);
                pulse_ns = end_ns - start_ns;
                break;
            }
        }

        if (!running) break;

        double time_s = (double)pulse_ns / 1000000000.0;
        double distance = (time_s * 34300.0) / 2.0;

        printf("Distance: %.2f cm\n", distance);

        if (gpiod_line_set_value(vcc, 0) < 0 ||
            gpiod_line_set_value(gnd, 1) < 0) {
            perror("set vcc/gnd low");
            break;
        }
        usleep(100000);
        if (gpiod_line_set_value(vcc, 1) < 0 ||
            gpiod_line_set_value(gnd, 0) < 0) {
            perror("set vcc/gnd high");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (vcc) gpiod_line_release(vcc);
    if (gnd) gpiod_line_release(gnd);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
