#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define BMP280_I2C_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp280_init(int fd) {
    if (i2c_write_reg8(fd, 0xE0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xE1, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF4, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF5, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF8, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, 0xF9, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFA, 0x2F) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFB, 0x06) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFC, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, 0xFD, 0x00) < 0) return -1;
    return 0;
}

static int bmp280_read_raw_temp(int fd, int32_t *raw_temp) {
    uint8_t buf[3];
    if (i2c_write_reg8(fd, 0xFA, 0x2E) < 0) return -1;
    if (i2c_read_reg16(fd, 0xFA, buf) < 0) return -1;
    *raw_temp = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp280_read_raw_press(int fd, int32_t *raw_press) {
    uint8_t buf[3];
    if (i2c_write_reg8(fd, 0xFA, 0x34) < 0) return -1;
    if (i2c_read_reg16(fd, 0xFA, buf) < 0) return -1;
    *raw_press = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bmp280_read(int fd, float *temp, float *press) {
    int32_t raw_temp, raw_press;
    if (bmp280_read_raw_temp(fd, &raw_temp) < 0) return -1;
    if (bmp280_read_raw_press(fd, &raw_press) < 0) return -1;
    *temp = ((raw_temp + 8) >> 4) / 10.0f;
    *press = ((raw_press + 8) >> 8) / 100.0f;
    return 0;
}

int main(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "Error initializing BMP280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int count = 0;
    while (running && count < 3) {
        float temp, press;
        if (bmp280_read(fd, &temp, &press) == 0) {
            printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);
            count++;
        } else {
            fprintf(stderr, "Error reading BMP280: %s\n", strerror(errno));
            break;
        }
        usleep(100000);
    }

    close(fd);
    return 0;
}

