    }

    /* Set the initial output state */
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    printf("GPIO %d set to LOW\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Main loop: run until interrupted */
    while (running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (value != 0 && value != 1) {
            fprintf(stderr, "Invalid GPIO value: %d (expected 0 or 1)\n", value);
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);
        fflush(stdout);

        /* Sleep 1 second; interruptible by signals */
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure the line is released */
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg24_le(int fd, uint8_t reg, int32_t *val) {
    uint8_t buf[3];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 3) != 3) return -1;
    *val = (int32_t)((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]);
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, 0xD0, &id) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x60)\n", id);
        return -1;
    }
    return 0;
}

static int bme280_read(int fd, int32_t *temp, int32_t *press, int32_t *hum) {
    uint8_t data[8];
    if (i2c_read_reg24_le(fd, 0xF7, temp) < 0) return -1;
    if (i2c_read_reg24_le(fd, 0xE7, press) < 0) return -1;
    if (i2c_read_reg24_le(fd, 0xE6, hum) < 0) return -1;
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: ioctl I2C_SLAVE 0x%02X failed: %s\n", BME280_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 init failed\n");
        goto cleanup;
    }

    printf("BME280 initialized. Reading 3 samples, 5 s interval.\n");
    for (int i = 0; i < 3 && running; i++) {
        int32_t temp, press, hum;
        if (bme280_read(fd, &temp, &press, &hum) == 0) {
            float t = temp / 100.0f;
            float p = press / 256.0f;
            float h = hum / 16384.0f;
            printf("T=%.2f C  P=%.2f hPa  H=%.2f %%\n", t, p, h);
        } else {
            fprintf(stderr, "Error: BME280 read failed: %s\n", strerror(errno));
        }
        sleep(5);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    printf("\nExiting cleanly.\n");
    return rc;
}

