#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10; /* 1 second timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = init_serial(SERIAL_PORT);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    while (running) {
        ssize_t bytes = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            break;
        }
        if (bytes == 0) {
            fprintf(stderr, "Device disconnected or not responding.\n");
            break;
        }

        buffer[bytes] = '\0';
        printf("Received: %s\n", buffer);
        fflush(stdout);

        usleep(100000); /* 0.1 seconds */
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hc-sr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        int val = gpiod_line_set_value(trigger, 1);
        if (val < 0) {
            perror("gpiod_line_set_value(trigger high)");
            goto cleanup;
        }
        usleep(10);

        val = gpiod_line_set_value(trigger, 0);
        if (val < 0) {
            perror("gpiod_line_set_value(trigger low)");
            goto cleanup;
        }
        usleep(60);

        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            goto cleanup;
        }

        int echo_us = val ? 0 : 1;
        usleep(1000);

        int val2 = gpiod_line_get_value(echo);
        if (val2 < 0) {
            perror("gpiod_line_get_value(echo low)");
            goto cleanup;
        }

        int echo_us2 = val2 ? 0 : 1;
        int pulse_us = echo_us2 - echo_us;

        if (pulse_us > 0 && pulse_us < 100000) {
            float distance = (float)pulse_us * 34300.0 / 2.0;
            printf("Distance: %.2f mm\n", distance);
            fflush(stdout);
            ret = EXIT_SUCCESS;
        } else {
            fprintf(stderr, "Invalid pulse reading (pulse_us=%d)\n", pulse_us);
        }

        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

