}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define ADXL345_ADDRESS 0x53
#define I2C_DEVICE "/dev/i2c-1"

static int g_fd = -1;

static void cleanup(int signum) {
    (void)signum;
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    exit(0);
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd) {
    uint8_t buf[2] = {0x2D, 0x33};
    if (i2c_write(fd, buf, 2) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int adxl345_read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = 0x32;
    uint8_t data[6];
    if (i2c_write(fd, &reg, 1) < 0) {
        return -1;
    }
    if (i2c_read(fd, data, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_fd = open(I2C_DEVICE, O_RDWR);
    if (g_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(g_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl");
        close(g_fd);
        return 1;
    }

    if (adxl345_init(g_fd) < 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        close(g_fd);
        return 1;
    }

    int16_t x, y, z;
    while (1) {
        if (adxl345_read_accel(g_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read failed\n");
            break;
        }
        printf("X: %6d, Y: %6d, Z: %6d\n", x, y, z);
        fflush(stdout);
        usleep(100000);
    }

    close(g_fd);
    return 0;
}

