#include <gpiod.h>

#define CONSUMER "rpi_gpio_control"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[8] = {NULL};
static const unsigned int offsets[8] = {0, 1, 2, 3, 4, 5, 12, 17};
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

static void release_resources(void) {
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", offsets[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output\n", offsets[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        int vals[8] = {0, 0, 0, 0, 0, 0, 0, 0};
        for (int i = 0; i < 8; i++) {
            vals[i] = 1;
            if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                fprintf(stderr, "Failed to set line %u\n", offsets[i]);
                release_resources();
                return EXIT_FAILURE;
            }
            printf("GPIO %u set to 1\n", offsets[i]);
        }
        sleep(1);
    }

    release_resources();
    return EXIT_SUCCESS;
}

