#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, 1000) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, 1000) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN_1, 0) != 0 ||
        gpioPWM(PWM_PIN_2, 0) != 0 ||
        gpioPWM(PWM_PIN_3, 0) != 0) {
        fprintf(stderr, "Failed to set initial PWM values\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM pins initialized. Press Ctrl+C to exit.\n");

    while (!terminate) {
        gpioPWM(PWM_PIN_1, 1);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        printf("PWM: ON (P1), OFF (P2), OFF (P3)\n");
        gpioDelay(1000000);
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 1);
        gpioPWM(PWM_PIN_3, 0);
        printf("PWM: OFF (P1), ON (P2), OFF (P3)\n");
        gpioDelay(1000000);
        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 1);
        printf("PWM: OFF (P1), OFF (P2), ON (P3)\n");
        gpioDelay(1000000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    printf("PWM terminated.\n");
    return EXIT_SUCCESS;
}

