    ret = gpiod_line_request_output(lines[1], CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output"); gpiod_chip_close(chip); return EXIT_FAILURE; }
    ret = gpiod_line_request_output(lines[2], CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output"); gpiod_chip_close(chip); return EXIT_FAILURE; }
    ret = gpiod_line_request_output(lines[3], CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output"); gpiod_chip_close(chip); return EXIT_FAILURE; }
    ret = gpiod_line_request_output(lines[4], CONSUMER, 0);
    if (ret < 0) { perror("gpiod_line_request_output"); gpiod_chip_close(chip); return EXIT_FAILURE; }
    ret = gpiod_line_request_output(lines[5], CONSUMER, 0);
