#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_RANGE 100
#define PWM_FREQ 1000
#define LOOP_DELAY_US 5000000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int vals[] = {1, 0, 0};
        for (size_t i = 0; i < sizeof(vals) / sizeof(vals[0]); ++i) {
            if (gpioPWM(pins[i], vals[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                running = 0;
                break;
            }
        }
        printf("GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               PWM_PIN_1, vals[0], PWM_PIN_2, vals[1], PWM_PIN_3, vals[2]);
        fflush(stdout);
        usleep(LOOP_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

